<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {t} from '../localization/language'
import {foregroundRefresh} from './foreground'
type Client={get<T>(url:string):Promise<T>;post<T>(url:string,data:unknown):Promise<T>}
const props=defineProps<{client:Client;provider?:boolean}>()
type Level={code:number;name:string;threshold:number;goodsRateBps:number;serviceRateBps:number;couponMinimumCents:number;couponValueCents:number;benefit:string}
type Config={levels:Level[];tasks:{kind:string;award:number;limit:number;period:string}[];monthlyGrowthLimit:number;monthlyDiscountLimitCents:number;goodsDiscountCapCents:number;serviceDiscountCapCents:number;observationDays:number;couponDays:number}
type Release={version:string;effectiveAt:number;createdAt:number;summary:string;status:string;config:Config}
type History={items:Release[];hasMore:boolean;currentVersion:string}
type Sample={total:number;beforeLevel:Level;afterLevel:Level;before:{payableCents:number};after:{payableCents:number}}
const root='/payments/growth/',history=ref<History>(),page=ref(1),draft=ref<Config>(),baseVersion=ref(''),version=ref(''),effective=ref(''),summary=ref(''),reason=ref(''),samples=ref<Sample[]>([]),previewSignature=ref(''),busy=ref(false),error=ref(''),notice=ref('')
const payload=computed(()=>({version:version.value,baseVersion:baseVersion.value,effectiveAt:Math.floor(new Date(effective.value+':00+08:00').getTime()/1000),summary:summary.value,config:draft.value}))
const signature=computed(()=>JSON.stringify(payload.value))
const canSubmit=computed(()=>!!previewSignature.value&&previewSignature.value===signature.value&&reason.value.trim().length>=5&&!busy.value)
let live=true,stop:undefined|(()=>void)
const stamp=(n:number)=>new Date(n*1000).toLocaleString(undefined,{timeZone:'Asia/Shanghai'})
const money=(n:number)=>(n/100).toFixed(2)
const labels:Record<string,string>={profile:'完善资料',learning:'每日学习',note:'记录行动',activity:'参与活动',review:'真实评价',current:'当前生效',scheduled:'待生效',historical:'历史版本',cancelled:'已取消'}
function copyCurrent(){const current=history.value?.items.find(r=>r.version===history.value?.currentVersion);if(!current)return;draft.value=JSON.parse(JSON.stringify(current.config));baseVersion.value=current.version;samples.value=[];previewSignature.value='';error.value='';}
async function load(){const requested=page.value;try{const h=await props.client.get<History>(root+(props.provider?'provider/rules':'admin/rules')+'?page='+requested);if(!live||requested!==page.value)return;history.value=h;if(!draft.value&&!props.provider)copyCurrent();error.value=''}catch(e){if(live)error.value=e instanceof Error?e.message:t('加载失败')}}
async function preview(){busy.value=true;error.value='';notice.value='';const captured=signature.value;try{const r=await props.client.post<{samples:Sample[]}>(root+'admin/rules/preview',{rule:payload.value});if(live&&captured===signature.value){samples.value=r.samples;previewSignature.value=captured}}catch(e){if(live)error.value=e instanceof Error?e.message:t('操作失败')}finally{if(live)busy.value=false}}
async function propose(kind:string,value:unknown){if(reason.value.trim().length<5){error.value=t('请填写至少五个字的变更理由');return}busy.value=true;error.value='';try{await props.client.post(root+'admin/proposal',{kind,payload:value,reason:reason.value});if(live){notice.value=t('已提交，等待另一位管理员复核');previewSignature.value='';window.dispatchEvent(new Event('askxuan:growth-changed'));await load()}}catch(e){if(live)error.value=e instanceof Error?e.message:t('操作失败')}finally{if(live)busy.value=false}}
function changePage(n:number){page.value=n;history.value=undefined;void load()}
onMounted(()=>{stop=foregroundRefresh(async current=>{if(current())await load()})})
onBeforeUnmount(()=>{live=false;stop?.()})
</script>
<template><section class="rule-manager"><h2>{{t('成长规则与历史版本')}}</h2><p>{{t('规则按北京时间生效，已支付订单沿用确认时的快照。')}}</p><p v-if="error" role="alert">{{t(error)}} <button @click="load">{{t('重试')}}</button></p><p v-if="notice" role="status">{{notice}}</p>
<details v-for="r in history?.items" :key="r.version"><summary>{{r.version}} · {{t(labels[r.status]||r.status)}} · {{stamp(r.effectiveAt||r.createdAt)}}</summary><p>{{t(r.summary)}}</p><div class="table-scroll"><table><thead><tr><th>{{t('等级')}}</th><th>{{t('成长门槛')}}</th><th>{{t('商品折扣')}}</th><th>{{t('服务折扣')}}</th><th>{{t('升级礼券')}}</th></tr></thead><tbody><tr v-for="l in r.config.levels" :key="l.code"><td>L{{l.code}} {{t(l.name)}}</td><td>{{l.threshold}}</td><td>{{l.goodsRateBps/1000}} {{t('折')}}</td><td>{{l.serviceRateBps/1000}} {{t('折')}}</td><td>¥{{money(l.couponMinimumCents)}}−{{money(l.couponValueCents)}}</td></tr></tbody></table></div><p v-for="x in r.config.tasks" :key="x.kind">{{t(labels[x.kind]||x.kind)}} +{{x.award}} · {{x.limit}} {{t(x.period==='day'?'每日':x.period==='month'?'每月':'一次')}}</p><p>{{t('周期任务月上限')}} {{r.config.monthlyGrowthLimit}} · {{t('月优惠上限')}} ¥{{money(r.config.monthlyDiscountLimitCents)}}</p><p>{{t('单单商品优惠上限')}} ¥{{money(r.config.goodsDiscountCapCents)}} · {{t('单单服务优惠上限')}} ¥{{money(r.config.serviceDiscountCapCents)}}</p><p>{{t('消费观察期')}} {{r.config.observationDays}} {{t('天')}} · {{t('礼券有效期')}} {{r.config.couponDays}} {{t('天')}}</p><p>{{t('成长值不可支付、兑换或转赠；随喜、运费、充值、押金、积分和模拟支付不计成长。折扣限已参与的商品和固定价服务，受服务方同意、预算及最低贡献约束。')}}</p><button v-if="!provider&&r.status==='scheduled'" :disabled="busy||reason.trim().length<5" @click="propose('rule_cancel',{version:r.version})">{{t('申请取消定时发布')}}</button></details>
<div><button :disabled="page===1||busy" @click="changePage(page-1)">{{t('上一页')}}</button><button :disabled="!history?.hasMore||busy" @click="changePage(page+1)">{{t('下一页')}}</button></div>
<template v-if="!provider&&draft"><h3>{{t('定时发布新规则')}}</h3><p>{{t('先预览样例，再提交复核。只有另一位管理员通过后，规则才会在设定时间生效。复核时须距生效至少一分钟，逾期请重新申请。')}}</p><p>{{t('编辑基于版本')}} {{baseVersion}} <button type="button" @click="copyCurrent">{{t('重新载入当前规则')}}</button></p>
<form @submit.prevent="preview"><div class="rule-fields"><label>{{t('新版本编号')}}<input v-model="version" required pattern="growth-[a-zA-Z0-9][a-zA-Z0-9._-]{0,23}" maxlength="32" placeholder="growth-20261020"/></label><label>{{t('生效时间（北京时间）')}}<input v-model="effective" type="datetime-local" required/></label><label>{{t('面向用户的变更说明')}}<textarea v-model="summary" required minlength="5" maxlength="500"/></label></div>
<fieldset v-for="l in draft.levels" :key="l.code"><legend>L{{l.code}} {{t(l.name)}}</legend><div class="rule-fields"><label>{{t('成长门槛')}}<input v-model.number="l.threshold" type="number" min="0" max="10000000" :disabled="l.code===1" required/></label><label>{{t('商品倍率（万分比）')}}<input v-model.number="l.goodsRateBps" type="number" min="5000" max="10000" :disabled="l.code===1" required/></label><label>{{t('服务倍率（万分比）')}}<input v-model.number="l.serviceRateBps" type="number" min="5000" max="10000" :disabled="l.code===1" required/></label><label>{{t('礼券门槛（分）')}}<input v-model.number="l.couponMinimumCents" type="number" min="0" max="100000000" :disabled="l.code===1" required/></label><label>{{t('礼券面额（分）')}}<input v-model.number="l.couponValueCents" type="number" min="0" max="10000" :disabled="l.code===1" required/></label></div></fieldset>
<fieldset><legend>{{t('任务与优惠上限')}}</legend><div class="rule-fields"><label v-for="x in draft.tasks" :key="x.kind">{{t(labels[x.kind]||x.kind)}}<input v-model.number="x.award" :aria-label="t(labels[x.kind]||x.kind)+' '+t('单次成长值')" type="number" min="1" max="200" required/><input v-model.number="x.limit" :aria-label="t(labels[x.kind]||x.kind)+' '+t('周期次数')" type="number" min="1" :max="x.period==='month'?31:1" :disabled="x.period!=='month'" required/></label><label>{{t('周期任务月上限')}}<input v-model.number="draft.monthlyGrowthLimit" type="number" min="1" max="10000" required/></label><label>{{t('月优惠上限（分，最高 30000）')}}<input v-model.number="draft.monthlyDiscountLimitCents" type="number" min="0" max="30000" required/></label><label>{{t('单单商品优惠上限（分）')}}<input v-model.number="draft.goodsDiscountCapCents" type="number" min="0" max="100000000" required/></label><label>{{t('单单服务优惠上限（分）')}}<input v-model.number="draft.serviceDiscountCapCents" type="number" min="0" max="100000000" required/></label></div><p>{{t('本规则系列保持七天观察期、礼券发放后有效三十天及北京时间边界不变。开关、项目参与和预算仍单独复核。')}}</p></fieldset>
<button :disabled="busy">{{t('预览五档核算')}}</button></form>
<template v-if="samples.length"><p>{{t('样例：商品 200 元、服务 100 元、不参与费用 30 元；仅演示规则算术，不代表项目已开放或预算充足。')}}</p><p v-if="previewSignature!==signature">{{t('草稿已变化，请重新预览')}}</p><div class="table-scroll"><table><thead><tr><th>{{t('成长值')}}</th><th>{{t('原等级')}}</th><th>{{t('新等级')}}</th><th>{{t('原应付')}}</th><th>{{t('新应付')}}</th></tr></thead><tbody><tr v-for="s in samples" :key="s.total"><td>{{s.total}}</td><td>L{{s.beforeLevel.code}}</td><td>L{{s.afterLevel.code}}</td><td>¥{{money(s.before.payableCents)}}</td><td>¥{{money(s.after.payableCents)}}</td></tr></tbody></table></div></template>
<label>{{t('变更理由（提交后由另一位管理员复核）')}}<textarea v-model="reason" minlength="5" maxlength="500"/></label><button :disabled="!canSubmit" @click="propose('rules',payload)">{{t('提交定时规则复核')}}</button>
</template></section></template>
<style scoped>.rule-manager{display:grid;gap:14px}h2,h3,p{margin:0}details{padding:12px 0;border-bottom:1px solid var(--el-border-color)}summary{min-height:36px;cursor:pointer;overflow-wrap:anywhere}.rule-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px}fieldset{border:1px solid var(--el-border-color);border-radius:10px;margin:16px 0;padding:16px}label{display:grid;gap:8px}input,textarea{font:inherit;background:var(--el-bg-color);color:var(--el-text-color-primary);border:1px solid var(--el-border-color);border-radius:6px;min-height:40px;padding:6px 10px;box-sizing:border-box;width:100%}button{font:inherit;min-height:44px;padding:8px 16px;margin-right:10px;border:1px solid var(--el-border-color);background:var(--el-bg-color);color:var(--el-text-color-primary);border-radius:8px;cursor:pointer}button:disabled{opacity:.5;cursor:default}.table-scroll{overflow:auto}table{border-collapse:collapse;width:100%;text-align:left}th,td{padding:12px;border-bottom:1px solid var(--el-border-color);white-space:nowrap}textarea{min-height:70px}input:focus-visible,button:focus-visible,textarea:focus-visible{outline:2px solid var(--el-color-primary);outline-offset:2px}</style>
